// Saved speech in Postgres: Buddy's lines are generated by ElevenLabs once, then served from here.
// Lines that are never reused (e.g. Chat Buddy's own replies) drop out after a few days; everything else
// after it has gone unused for a while, and the oldest go first if the table grows past its size limit.
import { q, one } from './db.js';

const KEEP_DAYS = () => Number(process.env.TTS_CACHE_KEEP_DAYS || 60);
const ONE_OFF_DAYS = () => Number(process.env.TTS_CACHE_ONE_OFF_DAYS || 3);
const MAX_MB = () => Number(process.env.TTS_CACHE_MAX_MB || 300);

export const pgSpeechStore = {
  async get(key) {
    const r = await one('update tts_cache set hits = hits + 1, last_used_at = now() where key=$1 returning audio', [key]);
    return r ? r.audio : null;
  },
  async put(key, audio, { model, voiceId, chars }) {
    await q('insert into tts_cache(key, model, voice_id, chars, audio, bytes) values ($1,$2,$3,$4,$5,$6) on conflict (key) do nothing',
      [key, model, voiceId, chars, audio, audio.length]);
  },
};

export async function pruneSpeech() {
  const a = await q(`delete from tts_cache where last_used_at < now() - make_interval(days => $1)
    or (hits = 0 and created_at < now() - make_interval(days => $2))`, [KEEP_DAYS(), ONE_OFF_DAYS()]);
  // Over the size limit: remove the least recently used until under it.
  const b = await q(`delete from tts_cache where key in (
      select key from (select key, sum(bytes) over (order by last_used_at desc) as running from tts_cache) t
      where running > $1::bigint * 1024 * 1024)`, [MAX_MB()]);
  return (a.rowCount || 0) + (b.rowCount || 0);
}

